import{_ as n,l as s,o as e,c as o,v as t,p as l,x as r,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"邻接表与邻接矩阵","description":"","frontmatter":{"title":"邻接表与邻接矩阵","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/adj-list-matrix.md","filePath":"cs/adj-list-matrix.md","lastUpdated":1789023840000}'),c={name:"cs/adj-list-matrix.md"};function m(E,a,_,T,u,f){const i=s("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="邻接表与邻接矩阵" tabindex="-1">邻接表与邻接矩阵 <a class="header-anchor" href="#邻接表与邻接矩阵" aria-label="Permalink to &quot;邻接表与邻接矩阵&quot;">​</a></h1><div class="epigraph"><p>图已经在离散课里定义；现在才选表示：矩阵用 $\\Theta(1)$ 问边，表用 $\\Theta(\\deg)$ 枚举邻居。</p><footer>—— 据 Cormen, Leiserson, Rivest and Stein, Introduction to Algorithms 整理</footer></div><p><a href="/cs/uf-rank-compress">上一课</a>能维护连通分量，却存不下边集。<a href="/cs/graph-definition">图的定义</a>已有顶点与边，当时没有布局。<a href="/cs/array-random-access">数组与随机访问</a>和<a href="/cs/linked-list-locality">链表与局部性代价</a>现在可以当零件。本课不重讲图的无环定义。缺口是两种标准表示：邻接矩阵与邻接表，以及它们把哪些操作写成 \\(\\Theta(1)\\) 或 \\(\\Theta(\\deg(v))\\)。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>ADT 层面图要：加点/边、问 \\((u,v)\\) 是否有边、枚举 \\(v\\) 的出边。矩阵 \\(A[u][v]=1\\) 让询问 \\(\\Theta(1)\\)，空间 \\(\\Theta(n^2)\\)，枚举一行 \\(\\Theta(n)\\) 即使度数是 1。表：每个 \\(v\\) 一条邻居列表，空间 \\(\\Theta(n+m)\\)，枚举 \\(\\Theta(\\deg(v))\\)，询问 \\((u,v)\\) 要扫 \\(u\\) 的表除非再加散列。</p><p>缺口不是「图是什么」，而是<strong>按将要做的操作选表示</strong>。后课稀疏图会把 \\(m\\ll n^2\\) 写成默认假设。</p><p><span class="marginnote">有向图用出边表；无向图每边存两次。权放在矩阵项或表节点上。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>矩阵： \\(n\\times n\\) 数组，适合稠密或需要快速边查询、乘法。表：数组 of 链表或动态数组，适合遍历。混合：表加边散列，两边都 \\(\\Theta(1)\\) 期望，空间仍 \\(\\Theta(n+m)\\)。</p>',9)),(e(),l(p,null,{default:r(()=>[h(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20G%5B%22%E5%9B%BE%20(V%2CE)%22%5D%20--%3E%20M%5B%22%E9%82%BB%E6%8E%A5%E7%9F%A9%E9%98%B5%20%CE%98(n%C2%B2)%22%5D%0A%20%20G%20--%3E%20L%5B%22%E9%82%BB%E6%8E%A5%E8%A1%A8%20%CE%98(n%2Bm)%22%5D%0A%20%20M%20--%3E%20Q1%5B%22%E9%97%AE%E8%BE%B9%20%CE%98(1)%22%5D%0A%20%20L%20--%3E%20Q2%5B%22%E6%9E%9A%E4%B8%BE%E9%82%BB%E5%B1%85%20%CE%98(deg)%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与<a href="/cs/locality-principle">局部性原理</a>：矩阵一行连续；链表邻居再追逐。邻居用动态数组则枚举吃空间局部性，删除边要另议。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>算法复杂度必须带着表示写：DFS 在表上 \\(\\Theta(n+m)\\)，在矩阵上 \\(\\Theta(n^2)\\)。同一伪代码，表示换了渐近就换。这是 ADT 课「合同含代价」在图上的落地。</p><p>并查集仍可并行维护分量，但不替代边表：Kruskal 要扫边列表，那份列表才是 \\(E\\) 的表示。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 CSR/CSC 压缩格式以外的科学计算细节，不把图数据库当正文。也不开始拓扑排序——DAG 下一课才限制边的方向无环。</p><p>后课默认：谈到图算法，先声明表还是矩阵。\\(m\\) 与 \\(n^2\\) 差一个数量级时，表是默认。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>矩阵：问边快，空间 \\(n^2\\)，枚举按 \\(n\\)。</li><li>表：空间 \\(n+m\\)，枚举按度数，问边要扫或加索引。</li><li>\\(m\\) 很小时的默认选择与 CSR，下一课稀疏图。</li><li>出处：Cormen et al. 第 22 章表示一节。</li></ul>',9))])}const C=n(c,[["render",m]]);export{A as __pageData,C as default};
